const chartPoints = [];
const latestGaugeData = {};

// 1. InfluxDB 데이터 안전 검증 및 루프 순회
if (Array.isArray(msg.payload)) {
    msg.payload.forEach(item => {
        const fieldName = item._field;
        let value = item._value;
        if (value === null || value === undefined) return;

        // 타임스탬프 밀리초 파싱 보장
        let timeMillis = 0;
        if (typeof item._time === 'number') {
            timeMillis = item._time;
        } else if (typeof item._time === 'string') {
            timeMillis = new Date(item._time).getTime();
        } else if (item._time instanceof Date) {
            timeMillis = item._time.getTime();
        }

        if (!timeMillis || isNaN(timeMillis)) {
            timeMillis = Date.now();
        }

        // 2. 전력 소비량 차트 데이터 적재 (차트 노드 설정인 category: topic에 대응)
        if (fieldName === "power_consumption") {
            chartPoints.push({
                x: timeMillis,             // xAxisProperty: "x"와 매칭
                y: Number(value.toFixed(1)) // yAxisProperty: "y"와 매칭
            });
        } else {
            // 3. 환경 센서 게이지 데이터 적재
            let roundedValue;
            if (fieldName === "temperature") {
                roundedValue = Number(value.toFixed(1)); 
            } else if (fieldName === "humidity" || fieldName === "co2" || fieldName === "lux") {
                roundedValue = Math.round(value); 
            } else {
                roundedValue = value;
            }

            latestGaugeData[fieldName] = roundedValue;
        }
    });
}

// --- 1번 출력 (위쪽 포트): Dashboard 2.0 ui-chart(category: topic) 전용 포맷 ---
// 차트 노드 설정이 "category": "topic" 이므로, msg.topic에 시리즈명을 넣고 payload에 순수 [{x, y}] 배열을 보냅니다.
const msgLine = {
    topic: "Power Consumption", // 차트 범례에 표시될 이름
    action: "replace",
    payload: chartPoints        // 순수 [{x: 타임스탬프, y: 값}] 구조의 플랫 배열
};

// --- 2번 출력 (아래쪽 포트): 게이지 노드용 스트림 분기 패킷 ---
const msgGauges = Object.keys(latestGaugeData).map(key => {
    return {
        topic: key,
        payload: latestGaugeData[key]
    };
});

return [msgLine, msgGauges];

const p = msg.payload;

// 유효성 검사: 객체가 아니거나 timestamp가 없으면 저장하지 않음
if (!p || typeof p !== 'object' || !p.timestamp) return null;

msg.topic = `INSERT INTO sensor_data
    (timestamp, temperature, humidity, co2, lux, occupied, power_consumption, quality_score)
    VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`;

msg.payload = [
    new Date(Number(p.timestamp)).toISOString(),
    p.temperature ?? null,
    p.humidity ?? null,
    p.co2 ?? null,
    p.lux ?? null,
    p.occupied === true || p.occupied === 'true',
    p.power_consumption ?? null,
    p.quality_score ?? null
];

return msg;

// ===== 기준값 (생성기와 동일하게 유지) =====
const LIMIT = {
    TEMP_LOW: 18,         // 이하 → 비정상 (HEAT_ON 대상)
    TEMP_HIGH: 27,        // 이상 → 비정상 (COOL_ON 대상)
    HUMI_LOW: 40,         // 미만 → 비정상
    HUMI_HIGH: 60,        // 초과 → 비정상
    CO2_WARN: 800,        // 초과 → 주의
    CO2_ABNORMAL: 1000    // 초과 → 비정상
};
const RATE_LIMIT = 4.5;   // 온도 변화율 허용치 (5초 기준)

// ===== 1건 평가 =====
function evaluate(p) {
    const issues = [];
    const skipRate = p.disable_rate_check ?? false;

    // 온도
    const lastTemp = context.get('lastTemp') ?? p.temperature;
    context.set('lastTemp', p.temperature);

    if (p.temperature <= LIMIT.TEMP_LOW) {
        issues.push({ label: 'Temperature low (HEAT_ON)', penalty: 35 });
    } else if (p.temperature >= LIMIT.TEMP_HIGH) {
        issues.push({ label: 'Temperature high (COOL_ON)', penalty: 35 });
    } else if (!skipRate && Math.abs(p.temperature - lastTemp) > RATE_LIMIT) {
        issues.push({ label: 'Abnormal temp change', penalty: 35 });
    }

    // 습도
    if (p.humidity < LIMIT.HUMI_LOW || p.humidity > LIMIT.HUMI_HIGH) {
        issues.push({ label: 'Humidity out of range (40~60)', penalty: 35 });
    }

    // CO2 (800 초과 주의, 1000 초과 비정상)
    if (p.co2 > LIMIT.CO2_ABNORMAL) {
        issues.push({ label: 'CO2 abnormal (>1000)', penalty: 35 });
    } else if (p.co2 > LIMIT.CO2_WARN) {
        issues.push({ label: 'CO2 warning (>800)', penalty: 15 });
    }

    const totalPenalty = issues.reduce((sum, i) => sum + i.penalty, 0);
    return {
        score: Math.max(0, 100 - totalPenalty),
        issues: issues.map(i => i.label)
    };
}

// ===== 평가 후 비정상만 insert 메시지로 변환 =====
const records = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const insertMsgs = [];

records.forEach(p => {
    if (!p || typeof p !== 'object') return;

    const r = evaluate(p);
    if (r.score >= 100) return;   // 정상 → 제외

    insertMsgs.push({
        topic: `INSERT INTO abnormal_data
                (event_time, temperature, humidity, co2, power_consumption,
                 quality_score, issues, system_state, anomaly_type)
                VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
        payload: [
            new Date(p.timestamp).toISOString(),
            p.temperature,
            p.humidity,
            p.co2,
            p.power_consumption,
            r.score,
            r.issues.join(', '),
            p.system_state ?? null,
            p.anomaly_type ?? null
        ]
    });
});

// 비정상이 없으면 아무것도 보내지 않음
if (insertMsgs.length === 0) return null;
return insertMsgs;

// 기존 데이터(msg.payload)는 온전히 유지하면서 eCharts 축 제어 옵션을 주입합니다.
msg.ui_update = {
    chartOptions: {
        xAxis: [
            {
                axisLabel: {
                    interval: 0,        // 0으로 지정하면 차트가 임의로 라벨을 생략하지 않고 모두 노출합니다.
                    hideOverlap: false  // 좁은 공간에서 글자가 약간 겹치더라도 숨기지 않고 강제 표시합니다.
                }
            }
        ]
    }
};

return msg;

msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': 'http://localhost:3000'
};
msg.payload = 'OK';
return msg;

const SECRET = 'demo-token-change-me';
if (msg.req.query.token !== SECRET) {
    msg.statusCode = 403;
    msg.payload = 'Forbidden';
    return msg;
}
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': 'http://localhost:3000'
};

const sim = flow.get('simDay');
const view = flow.get('simView');
if (sim && sim.active && view) {
    msg.payload = view;
} else {
    msg.payload = flow.get('simStatus') || { stage: 'NORMAL', equipment: {} };
}
return msg;

const SECRET = 'demo-token-change-me';

if (msg.req.query.token !== SECRET) {
    return [msg, null];   // 출력1: 실패
}
return [null, msg];       // 출력2: 통과

msg.statusCode = 403;
msg.headers = { 'Access-Control-Allow-Origin': 'http://localhost:3000' };
msg.payload = 'Forbidden';
return msg;

// 1. 상태 로드 (40실, 0명 초기화)
const sim = flow.get('simDay');
const KEY = (sim && sim.active) ? 'roomsDemo' : 'rooms';
let rooms = flow.get(KEY);
if (!rooms) {
    rooms = {};
    for (let f = 1; f <= 10; f++) {
        for (const r of ['A', 'B', 'C', 'D']) {
            rooms[`${f}F_${r}`] = 0;
        }
    }
}

// 2. 시각 결정: 데모 중이면 가상 시각, 아니면 실제 시각


const demo = !!(sim && sim.active);
let minuteOfDay;
if (demo) {
    minuteOfDay = sim.simMinute;
} else {
    const now = new Date();
    minuteOfDay = now.getHours() * 60 + now.getMinutes();
}

// 3. 점유율 앵커 (수용 400명 기준)
const CAPACITY = 400;
const DEMO_ANCHORS = [
    { m: 16 * 60, pct: 0.80 },
    { m: 17 * 60, pct: 0.70 },
    { m: 18 * 60, pct: 0.30 },
    { m: 19 * 60, pct: 0.10 },
    { m: 20 * 60, pct: 0.05 },
    { m: 21 * 60, pct: 0.03 },
    { m: 22 * 60, pct: 0.01 }
];
const NORMAL_ANCHORS = [
    { m: 0,       pct: 0.05 },
    { m: 7 * 60,  pct: 0.05 },
    { m: 9 * 60,  pct: 0.90 },
    { m: 13 * 60, pct: 0.70 },
    { m: 17 * 60, pct: 0.70 },
    { m: 19 * 60, pct: 0.05 },
    { m: 24 * 60, pct: 0.05 }
];
const A = demo ? DEMO_ANCHORS : NORMAL_ANCHORS;

function pctAt(m) {
    if (m <= A[0].m) return A[0].pct;
    for (let i = 0; i < A.length - 1; i++) {
        const a = A[i], b = A[i + 1];
        if (m >= a.m && m <= b.m) {
            return a.pct + (b.pct - a.pct) * (m - a.m) / (b.m - a.m);
        }
    }
    return A[A.length - 1].pct;
}

const targetTotal = Math.round(pctAt(minuteOfDay) * CAPACITY);

// 4. 목표 인원에 맞춰 실별 무작위 증감 (실당 0~10명)
let currentTotal = Object.values(rooms).reduce((a, b) => a + b, 0);
const gap = targetTotal - currentTotal;
const moves = Math.min(Math.abs(gap), 400);   // 틱당 최대 400명 이동
const dir = gap > 0 ? 1 : -1;

const keys = Object.keys(rooms);
for (let i = 0; i < moves; i++) {
    const candidates = keys.filter(k => dir > 0 ? rooms[k] < 10 : rooms[k] > 0);
    if (candidates.length === 0) break;
    const key = candidates[Math.floor(Math.random() * candidates.length)];
    rooms[key] += dir;
    currentTotal += dir;
}

// 5. 상태 저장
flow.set(KEY, rooms);
// 6. 다음 노드로 전달
msg.rooms = rooms;
msg.totalPeople = currentTotal;
msg.targetPct = Math.round(pctAt(minuteOfDay) * 1000) / 10;
msg.minuteOfDay = minuteOfDay;
msg.demo = demo;
return msg;

// 버튼/HTTP 명령을 읽어 상태 명령으로 정리
const CMD_MAP = {
    ANOMALY_TEMP: 'temp',
    ANOMALY_TEMP_LOW: 'tempLow',
    ANOMALY_HUMI: 'humi',
    ANOMALY_CO2: 'co2'
};


let raw;
if (msg.req && msg.req.query && msg.req.query.action !== undefined) {
    raw = msg.req.query.action;
} else if (typeof msg.payload === 'string') {
    raw = msg.payload;
}
const cmd = (raw === undefined) ? 'TICK' : String(raw).trim().toUpperCase();

let s = flow.get('state') || {
    anomaly: null, equipOn: false, detectTicks: 0, recovered: false,
    temp: 22.0, humi: 45.0, co2: 550, lux: 350, occupied: false,
    view: null
};

if (CMD_MAP[cmd] !== undefined) {
    if (s.anomaly !== CMD_MAP[cmd]) {
        s.anomaly = CMD_MAP[cmd];
        s.equipOn = false;
        s.detectTicks = 0;
        s.recovered = false;
    }
} else if (cmd === 'RESET') {
    s.anomaly = null;
    s.equipOn = false;
    s.detectTicks = 0;
    s.recovered = false;
} else if (cmd === 'OCCUPY_ON') {
    s.occupied = true;
} else if (cmd === 'OCCUPY_OFF') {
    flow.set('simDay', {
        active: true,
        startMinute: 16 * 60,   // 16:00
        endMinute: 22 * 60,     // 22:00
        simMinute: 16 * 60,
        stepMinute: 60,         // 틱당 15분 (5초 틱 기준 약 2분에 완료)
        ticks: 0
    });
}else if (cmd !== 'TICK') {
    node.warn(`알 수 없는 명령: [${cmd}]`);
}


flow.set('state', s);
msg.state = s;
return msg;

// ---------- 설정 ----------
const SC = {
    temp:    { sensor: 'temp', dir: 'high', detect: 28,   severe: 30,   ok: 24,  rise: 3.0,  fall: 3.0,  noise: 0.4, cap: 45.0 },
    tempLow: { sensor: 'temp', dir: 'low',  detect: 18,   severe: 15,   ok: 20,  rise: 3.0,  fall: 3.0,  noise: 0.4, cap: 5.0  },
    humi:    { sensor: 'humi', dir: 'high', detect: 60,   severe: 75,   ok: 55,  rise: 8.0,  fall: 11.5, noise: 0.8, cap: 100.0 },
    co2:     { sensor: 'co2',  dir: 'high', detect: 1000, severe: 1300, ok: 900, rise: 250,  fall: 220,  noise: 20,  cap: 3000 }
};
const AUTO_START_TICKS = 4;
const NORMAL_TARGET = { temp: 22.0, humi: 45.0, co2: 500, co2Occupied: 650 };

const noise = (amp) => (Math.random() - 0.5) * amp;
const isBeyond = (L, x, lim) => (L.dir === 'high' ? x >= lim : x <= lim);
const isRecovered = (L, x) => (L.dir === 'high' ? x <= L.ok : x >= L.ok);

// ---------- 상태 ----------
const s = flow.get('state') || msg.state;
// 이상 센서: 이상 방향 변화 / 장비 가동 중에는 정상 방향 변화
function stepAnomaly(st) {
    if (!st.anomaly) return;
    const L = SC[st.anomaly];
    const k = (L.dir === 'high') ? 1 : -1;
    if (st.equipOn) st[L.sensor] -= k * L.fall + noise(L.noise);
    else            st[L.sensor] += k * L.rise + noise(L.noise);
    st[L.sensor] = (L.dir === 'high')
        ? Math.min(st[L.sensor], L.cap)
        : Math.max(st[L.sensor], L.cap);

}

// 정상 센서: 목표값 주변 변동 (이상 센서 제외)
function stepNormal(st) {
    const anomSensor = st.anomaly ? SC[st.anomaly].sensor : null;
    if (anomSensor !== 'temp') st.temp += (NORMAL_TARGET.temp - st.temp) * 0.1 + noise(0.3);
    if (anomSensor !== 'humi') st.humi += (NORMAL_TARGET.humi - st.humi) * 0.1 + noise(1.0);
    if (anomSensor !== 'co2') {
        const target = st.occupied ? NORMAL_TARGET.co2Occupied : NORMAL_TARGET.co2;
        st.co2 += (target - st.co2) * 0.1 + noise(20);
    }
}

// 장비 가동 / 정상 복귀 판정
function judgeScenario(st) {
    if (!st.anomaly) return;
    const L = SC[st.anomaly];
    const v = st[L.sensor];
    if (!st.equipOn) {
        st.detectTicks = isBeyond(L, v, L.detect) ? st.detectTicks + 1 : 0;
        if (isBeyond(L, v, L.severe) || st.detectTicks >= AUTO_START_TICKS) {
            st.equipOn = true;
        }
    } else if (isRecovered(L, v)) {
        st.anomaly = null;
        st.equipOn = false;
        st.detectTicks = 0;
        st.recovered = true;
    }
}

// 단계(stage) 계산

function calcStage(st) {
    if (!st.anomaly) return st.recovered ? 'RECOVERED' : 'NORMAL';
    const L = SC[st.anomaly];
    const v = st[L.sensor];
    if (st.equipOn) return 'MITIGATING';
    if (isBeyond(L, v, L.severe)) return 'SEVERE';
    if (isBeyond(L, v, L.detect)) return 'DETECTED';
    return 'NORMAL';   // 기준 도달 전에는 정상 표시 (ANOMALY 단계 제거)
}

// 조도: 외부 일사량 + 실내 조명
function stepLux(st) {
    const now = new Date();
    const hour = now.getHours() + now.getMinutes() / 60;
    let outdoor = 0;
    if (hour > 6 && hour < 19) outdoor = Math.sin(Math.PI * (hour - 6) / 13) * 1000;
    outdoor = Math.max(0, outdoor + noise(60));
    const lightOn = st.occupied && outdoor < 400;
    const indoorTarget = outdoor * 0.3 + (lightOn ? 350 : 0);
    st.lux += (indoorTarget - st.lux) * 0.3 + noise(5);
    st.lux = Math.min(Math.max(st.lux, 0), 1000);
    return { outdoor, lightOn };
}

stepAnomaly(s);
stepNormal(s);
judgeScenario(s);
const stage = calcStage(s);
const envInfo = stepLux(s);


// 직전 틱 판정을 표시용으로 사용 (수치 변화 이후 점등)
const cur = { anomaly: s.anomaly, equipOn: s.equipOn, stage: stage };
const shown = s.view || cur;
s.view = cur;
node.warn('engine: anomaly=' + s.anomaly + ' temp=' + s.temp.toFixed(1) + ' equipOn=' + s.equipOn + ' stage=' + stage);
flow.set('state', s);
// 다음 노드로 전달
msg.state = s;
msg.shown = shown;
msg.envInfo = envInfo;


return msg;

const sim = flow.get('simDay');
if (sim && sim.active) {
    // 라이팅 시연 중에는 InfluxDB/AWS 게시 생략 (시연 값은 flow에만)
    return null;
}

const s = msg.state;
const shown = msg.shown;

// 1. 장비 가동 상태 (직전 틱 판정 기준)
const equip = {
    chiller: shown.anomaly === 'temp' && shown.equipOn,
    heater: shown.anomaly === 'tempLow' && shown.equipOn,
    humidifier: false,
    dehumidifier: shown.anomaly === 'humi' && shown.equipOn,
    ahu: shown.anomaly === 'co2' && shown.equipOn
};

// 2. 장비/환기 상태 문자열
let hvac = "OFF";
if (s.temp > 28) hvac = "COOL_ON";
else if (s.temp < 18) hvac = "HEAT_ON";
if (equip.chiller) hvac = "COOL_ON";
if (equip.heater) hvac = "HEAT_ON";

let humiStatus = "OFF";
if (s.humi < 40) humiStatus = "HUMIDIFIER_ON";
else if (s.humi > 60) humiStatus = "DEHUMIDIFIER_ON";
if (equip.dehumidifier) humiStatus = "DEHUMIDIFIER_ON";

let vent = "OFF";
if (s.co2 > 1000) vent = "VENT_HIGH";
else if (s.co2 > 800) vent = "VENT_LOW";
if (equip.ahu) vent = "AHU_FRESH_AIR";

// 3. 전력 계산 (조명계산 결과 기준)
let power = Math.floor(Math.random() * (520 - 470) + 470);
if (hvac !== "OFF") power += 200;
if (equip.dehumidifier) power += 120;
if (equip.ahu) power += 150;
if (equip.heater) power += 150;
if (msg.litCount > 0) power += 100;

// 4. 통합 payload (인원·조명·장비·센서를 같은 timestamp로)
const payload = {
    timestamp: Date.now(),
    temperature: parseFloat(s.temp.toFixed(1)),
    humidity: Math.round(s.humi),
    co2: Math.floor(s.co2),
    lux: msg.lux,
    outdoor_lux: msg.outdoor,
    lit_rooms: msg.litCount,
    occupied: s.occupied,
    power_consumption: power,
    hvac_status: hvac,
    humidity_status: humiStatus,
    vent_status: vent,
    light_status: msg.litCount > 0 ? "LIGHT_ON" : "OFF",
    system_state: shown.equipOn ? "RECOVERING" : (shown.anomaly ? "ANOMALY" : "NORMAL"),
    stage: shown.stage,
    anomaly_type: shown.anomaly,
    disable_rate_check: s.anomaly !== null
};

// 5. 방별 인원을 평면 필드로 추가 (occ_1F_A 등)
for (const key of Object.keys(msg.rooms)) {
    payload[`occ_${key}`] = msg.rooms[key];
}

msg.payload = payload;
msg.equip = equip;
return msg;

// 상태저장 노드
const p = msg.payload;

flow.set('simStatus', {
    timestamp: p.timestamp,
    mode: 'REAL',
    stage: p.stage,
    anomaly_type: p.anomaly_type,
    equipment: msg.equip,
    temperature: p.temperature,
    humidity: p.humidity,
    co2: p.co2,
    lux: p.lux,
    lit_rooms: p.lit_rooms,
    occupied: p.occupied,
    occupancy: msg.rooms        // 실시간 방별 인원
});

return msg;

// ===== Lux계산: 실별 조도 → 건물 평균 =====
const LUX_OCCUPIED = 400;   // 재실 실 조도
const LUX_EMPTY = 0;     // 빈 실 조도

const rooms = msg.rooms;
const keys = Object.keys(rooms);
const totalRooms = keys.length;   // 40

const lightState = {};
let litCount = 0;
let sumLux = 0;

for (const key of keys) {
    const occupied = rooms[key] > 0;   // 1명 이상이면 재실
    lightState[key] = occupied;
    if (occupied) litCount++;
    sumLux += occupied ? LUX_OCCUPIED : LUX_EMPTY;
}

// 건물 평균 조도 = 전체 실 조도 합 ÷ 전체 실 수 (빈 실 0 포함)
const avgLux = totalRooms > 0 ? sumLux / totalRooms : 0;

msg.lightState = lightState;
msg.lux = Math.round(avgLux * 10) / 10;   // 소수 첫째 자리
msg.litCount = litCount;
const hour = new Date().getHours() + new Date().getMinutes() / 60;
msg.outdoor = Math.round(hour > 6 && hour < 19 ? Math.sin(Math.PI * (hour - 6) / 13) * 1000 : 0);
return msg;

const sim = flow.get('simDay');
if (sim && sim.active) {
    sim.ticks++;
    if (sim.simMinute >= sim.endMinute) {
        sim.active = false;          // 22:00 상태를 한 번 표시한 뒤 종료
    } else {
        sim.simMinute += sim.stepMinute;
    }
    flow.set('simDay', sim);
}
return msg;

const BASELINE_LUX = 400;
const lux = msg.lux ?? 0;
const savingsPct = Number(((BASELINE_LUX - lux) / BASELINE_LUX * 100).toFixed(1));

const sim = flow.get('simDay');
if (msg.demo && sim) {
    const m = msg.minuteOfDay;
    const hh = String(Math.floor(m / 60)).padStart(2, '0');
    const mm = String(m % 60).padStart(2, '0');
    const progress = (m - sim.startMinute) / (sim.endMinute - sim.startMinute) * 100;

    flow.set('simView', {
        mode: 'DEMO',
        time: `${hh}:${mm}`,
        people: msg.totalPeople ?? 0,
        outdoor_lux: msg.outdoor ?? 0,
        lux: lux,
        savings_pct: savingsPct,
        occupancy: msg.rooms,
        progress_pct: Math.min(100, Math.max(0, Math.round(progress)))
    });
} else {
    // 데모가 끝나면 화면 상태를 일반 모드로 되돌림
    flow.set('simView', null);
}
return msg;

const chartPoints = [];
const latestGaugeData = {};

// 1. InfluxDB 데이터 안전 검증 및 루프 순회
if (Array.isArray(msg.payload)) {
    msg.payload.forEach(item => {
        const fieldName = item._field;
        let value = item._value;
        if (value === null || value === undefined) return;

        // 타임스탬프 밀리초 파싱 보장
        let timeMillis = 0;
        if (typeof item._time === 'number') {
            timeMillis = item._time;
        } else if (typeof item._time === 'string') {
            timeMillis = new Date(item._time).getTime();
        } else if (item._time instanceof Date) {
            timeMillis = item._time.getTime();
        }

        if (!timeMillis || isNaN(timeMillis)) {
            timeMillis = Date.now();
        }

        // 2. 전력 소비량 차트 데이터 적재 (차트 노드 설정인 category: topic에 대응)
        if (fieldName === "power_consumption") {
            chartPoints.push({
                x: timeMillis,             // xAxisProperty: "x"와 매칭
                y: Number(value.toFixed(1)) // yAxisProperty: "y"와 매칭
            });
        } else {
            // 3. 환경 센서 게이지 데이터 적재
            let roundedValue;
            if (fieldName === "temperature") {
                roundedValue = Number(value.toFixed(1)); 
            } else if (fieldName === "humidity" || fieldName === "co2" || fieldName === "lux") {
                roundedValue = Math.round(value); 
            } else {
                roundedValue = value;
            }

            latestGaugeData[fieldName] = roundedValue;
        }
    });
}

// --- 1번 출력 (위쪽 포트): Dashboard 2.0 ui-chart(category: topic) 전용 포맷 ---
// 차트 노드 설정이 "category": "topic" 이므로, msg.topic에 시리즈명을 넣고 payload에 순수 [{x, y}] 배열을 보냅니다.
const msgLine = {
    topic: "Power Consumption", // 차트 범례에 표시될 이름
    action: "replace",
    payload: chartPoints        // 순수 [{x: 타임스탬프, y: 값}] 구조의 플랫 배열
};

// --- 2번 출력 (아래쪽 포트): 게이지 노드용 스트림 분기 패킷 ---
const msgGauges = Object.keys(latestGaugeData).map(key => {
    return {
        topic: key,
        payload: latestGaugeData[key]
    };
});

return [msgLine, msgGauges];

const p = msg.payload;

// 유효성 검사: 객체가 아니거나 timestamp가 없으면 저장하지 않음
if (!p || typeof p !== 'object' || !p.timestamp) return null;

msg.topic = `INSERT INTO sensor_data
    (timestamp, temperature, humidity, co2, lux, occupied, power_consumption, quality_score)
    VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`;

msg.payload = [
    new Date(Number(p.timestamp)).toISOString(),
    p.temperature ?? null,
    p.humidity ?? null,
    p.co2 ?? null,
    p.lux ?? null,
    p.occupied === true || p.occupied === 'true',
    p.power_consumption ?? null,
    p.quality_score ?? null
];

return msg;

// ===== 기준값 (생성기와 동일하게 유지) =====
const LIMIT = {
    TEMP_LOW: 18,         // 이하 → 비정상 (HEAT_ON 대상)
    TEMP_HIGH: 27,        // 이상 → 비정상 (COOL_ON 대상)
    HUMI_LOW: 40,         // 미만 → 비정상
    HUMI_HIGH: 60,        // 초과 → 비정상
    CO2_WARN: 800,        // 초과 → 주의
    CO2_ABNORMAL: 1000    // 초과 → 비정상
};
const RATE_LIMIT = 4.5;   // 온도 변화율 허용치 (5초 기준)

// ===== 1건 평가 =====
function evaluate(p) {
    const issues = [];
    const skipRate = p.disable_rate_check ?? false;

    // 온도
    const lastTemp = context.get('lastTemp') ?? p.temperature;
    context.set('lastTemp', p.temperature);

    if (p.temperature <= LIMIT.TEMP_LOW) {
        issues.push({ label: 'Temperature low (HEAT_ON)', penalty: 35 });
    } else if (p.temperature >= LIMIT.TEMP_HIGH) {
        issues.push({ label: 'Temperature high (COOL_ON)', penalty: 35 });
    } else if (!skipRate && Math.abs(p.temperature - lastTemp) > RATE_LIMIT) {
        issues.push({ label: 'Abnormal temp change', penalty: 35 });
    }

    // 습도
    if (p.humidity < LIMIT.HUMI_LOW || p.humidity > LIMIT.HUMI_HIGH) {
        issues.push({ label: 'Humidity out of range (40~60)', penalty: 35 });
    }

    // CO2 (800 초과 주의, 1000 초과 비정상)
    if (p.co2 > LIMIT.CO2_ABNORMAL) {
        issues.push({ label: 'CO2 abnormal (>1000)', penalty: 35 });
    } else if (p.co2 > LIMIT.CO2_WARN) {
        issues.push({ label: 'CO2 warning (>800)', penalty: 15 });
    }

    const totalPenalty = issues.reduce((sum, i) => sum + i.penalty, 0);
    return {
        score: Math.max(0, 100 - totalPenalty),
        issues: issues.map(i => i.label)
    };
}

// ===== 평가 후 비정상만 insert 메시지로 변환 =====
const records = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const insertMsgs = [];

records.forEach(p => {
    if (!p || typeof p !== 'object') return;

    const r = evaluate(p);
    if (r.score >= 100) return;   // 정상 → 제외

    insertMsgs.push({
        topic: `INSERT INTO abnormal_data
                (event_time, temperature, humidity, co2, power_consumption,
                 quality_score, issues, system_state, anomaly_type)
                VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
        payload: [
            new Date(p.timestamp).toISOString(),
            p.temperature,
            p.humidity,
            p.co2,
            p.power_consumption,
            r.score,
            r.issues.join(', '),
            p.system_state ?? null,
            p.anomaly_type ?? null
        ]
    });
});

// 비정상이 없으면 아무것도 보내지 않음
if (insertMsgs.length === 0) return null;
return insertMsgs;

// ===== 0. 설정 =====
// dir: 'high' = 값이 detect 이상이면 이상, 'low' = 값이 detect 이하이면 이상
const LIMIT = {
    temp:    { sensor: 'temp', dir: 'high', detect: 28,   severe: 30,   ok: 24 },  // 고온 (28 이상 이상, 24 이하 정상 복귀)
    tempLow: { sensor: 'temp', dir: 'low',  detect: 18,   severe: 15,   ok: 20 },  // 저온 (18 이하 이상, 20 이상 정상 복귀)
    humi:    { sensor: 'humi', dir: 'high', detect: 60,   severe: 75,   ok: 55 },
    co2:     { sensor: 'co2',  dir: 'high', detect: 1000, severe: 1300, ok: 900 }
};
const AUTO_START_TICKS = 2;   // 감지 후 10초(2틱) 안에 개선 없으면 자동 가동

// 틱(5초)당 변화량: 이상 방향으로는 rise, 정상 방향으로는 장비 가동 후 fall
const RATE = {
    temp:    { rise: 3.0,  fall: 3.0 },
    tempLow: { rise: 3.0,  fall: 3.0 },
    humi:    { rise: 8.0,  fall: 11.5 },
    co2:     { rise: 250,  fall: 220 }
};
const NOISE = { temp: 0.4, humi: 0.8, co2: 20 };          // 이상 센서 노이즈 진폭
const CAP   = { temp: 45.0, tempLow: 5.0, humi: 100.0, co2: 3000 };  // 시뮬레이션 한계값

// ===== 1. 상태 로드 =====
let s = context.get('state') || {
    anomaly: null, equipOn: false, detectTicks: 0, recovered: false,
    temp: 22.0, humi: 45.0, co2: 550, lux: 350, occupied: false,
    view: null   // 직전 틱의 판정 결과 (램프/장비 표시용)
};

// ===== 2. 명령 처리 (버튼/HTTP 공통) =====
function extractCommand(m) {
    let raw;
    if (m.req && m.req.query && m.req.query.action !== undefined) {
        raw = m.req.query.action;          // 버튼 요청: 쿼리 파라미터 우선
    } else if (typeof m.payload === 'string') {
        raw = m.payload;                   // 그 외 문자열 명령(테스트용)
    }
    if (raw === undefined) return 'TICK';
    return String(raw).trim().toUpperCase();
}

const cmd = extractCommand(msg);
const ANOMALY_CMD = {
    ANOMALY_TEMP: 'temp',           // 고온
    ANOMALY_TEMP_LOW: 'tempLow',    // 저온
    ANOMALY_HUMI: 'humi',
    ANOMALY_CO2: 'co2'
};

if (ANOMALY_CMD[cmd] !== undefined) {
    if (s.anomaly !== ANOMALY_CMD[cmd]) {
        s.anomaly = ANOMALY_CMD[cmd];
        s.equipOn = false;
        s.detectTicks = 0;
        s.recovered = false;        // 새 이상이면 정상화 표시 해제
    }
} else if (cmd === 'RESET') {
    s.anomaly = null;
    s.equipOn = false;
    s.detectTicks = 0;
    s.recovered = false;            // 초기화 시 정상 운전으로
} else if (cmd === 'OCCUPY_ON') {
    s.occupied = true;
} else if (cmd === 'OCCUPY_OFF') {
    s.occupied = false;
} else if (cmd !== 'TICK') {
    node.warn(`알 수 없는 명령: [${cmd}]`);
}

// ===== 3. 값 계산 =====
const noise = (amp) => (Math.random() - 0.5) * amp;

// 이상 여부 판단 helper
const isBeyond = (L, x, lim) => (L.dir === 'high' ? x >= lim : x <= lim);   // 한계 이상/이하 도달
const isRecovered = (L, x) => (L.dir === 'high' ? x <= L.ok : x >= L.ok);   // 정상 범위 복귀
const isAnomSensor = (sensor) => !!s.anomaly && LIMIT[s.anomaly].sensor === sensor;

// 3-1. 이상 센서: 이상 방향으로 매 틱 변화, 장비 가동 중에는 정상 방향으로 변화
if (s.anomaly) {
    const A = s.anomaly;
    const L = LIMIT[A];
    const key = L.sensor;
    const k = (L.dir === 'high') ? 1 : -1;   // 이상 방향 부호
    const r = RATE[A];

    if (s.equipOn) s[key] -= k * r.fall + noise(NOISE[key]);
    else           s[key] += k * r.rise + noise(NOISE[key]);

    // 시뮬레이션 한계값 적용
    s[key] = (L.dir === 'high') ? Math.min(s[key], CAP[A]) : Math.max(s[key], CAP[A]);
}

// 3-2. 정상 센서: 목표값 주변 변동 (이상 센서 제외)
const target = { temp: 22.0, humi: 45.0, co2: s.occupied ? 650 : 500 };
if (!isAnomSensor('temp')) s.temp += (target.temp - s.temp) * 0.1 + noise(0.3);
if (!isAnomSensor('humi')) s.humi += (target.humi - s.humi) * 0.1 + noise(1.0);
if (!isAnomSensor('co2'))  s.co2  += (target.co2  - s.co2)  * 0.1 + noise(20);

// 3-3. 시나리오 자동 판단
if (s.anomaly) {
    const L = LIMIT[s.anomaly];
    const v = s[L.sensor];

    if (!s.equipOn) {
        s.detectTicks = isBeyond(L, v, L.detect) ? s.detectTicks + 1 : 0;
        // 심각 도달 즉시, 또는 감지 상태가 2틱(10초) 유지되면 자동 가동
        if (isBeyond(L, v, L.severe) || s.detectTicks >= AUTO_START_TICKS) {
            s.equipOn = true;
        }
    } else if (isRecovered(L, v)) {
        // 정상 범위 복귀 → 장비 자동 정지, 정상화 표시 유지
        s.anomaly = null;
        s.equipOn = false;
        s.detectTicks = 0;
        s.recovered = true;
    }
}

// 3-4. 단계(stage) 계산
let stage;
if (s.anomaly) {
    const L = LIMIT[s.anomaly];
    const v = s[L.sensor];
    if (s.equipOn) stage = 'MITIGATING';
    else if (isBeyond(L, v, L.severe)) stage = 'SEVERE';
    else if (isBeyond(L, v, L.detect)) stage = 'DETECTED';
    else stage = 'ANOMALY';
} else {
    stage = s.recovered ? 'RECOVERED' : 'NORMAL';
}

// 3-5. 조도: 외부 일사량 + 실내 조명
const now = new Date();
const hour = now.getHours() + now.getMinutes() / 60;
let outdoor = 0;
if (hour > 6 && hour < 19) outdoor = Math.sin(Math.PI * (hour - 6) / 13) * 1000;
outdoor = Math.max(0, outdoor + noise(60));

const lightOn = s.occupied && outdoor < 400;
const indoorTarget = outdoor * 0.3 + (lightOn ? 350 : 0);
s.lux += (indoorTarget - s.lux) * 0.3 + noise(5);
s.lux = Math.min(Math.max(s.lux, 0), 1000);

// 3-6. 판정 결과 보관: 램프/장비는 직전 틱 판정을 사용 (수치 변화 이후에 점등)
const cur = { anomaly: s.anomaly, equipOn: s.equipOn, stage: stage };
const shown = s.view || cur;
s.view = cur;

context.set('state', s);

// ===== 4. 장비 및 파생 상태 =====
const temp = s.temp, humi = s.humi, co2 = s.co2, lux = s.lux;
const occupied = s.occupied;

const equip = {
    chiller: shown.anomaly === 'temp' && shown.equipOn,
    heater: shown.anomaly === 'tempLow' && shown.equipOn,
    humidifier: false,
    dehumidifier: shown.anomaly === 'humi' && shown.equipOn,
    ahu: shown.anomaly === 'co2' && shown.equipOn
};

let hvac_status = "OFF";
if (temp > 28) hvac_status = "COOL_ON";
else if (temp < 18) hvac_status = "HEAT_ON";
if (equip.chiller) hvac_status = "COOL_ON";
if (equip.heater) hvac_status = "HEAT_ON";

let humi_status = "OFF";
if (humi < 40) humi_status = "HUMIDIFIER_ON";
else if (humi > 60) humi_status = "DEHUMIDIFIER_ON";
if (equip.dehumidifier) humi_status = "DEHUMIDIFIER_ON";

let vent_status = "OFF";
if (co2 > 1000) vent_status = "VENT_HIGH";
else if (co2 > 800) vent_status = "VENT_LOW";
if (equip.ahu) vent_status = "AHU_FRESH_AIR";

const light_status = lightOn ? "LIGHT_ON" : "OFF";

let basePower = Math.floor(Math.random() * (520 - 470) + 470);
if (hvac_status !== "OFF") basePower += 200;
if (equip.dehumidifier) basePower += 120;
if (equip.ahu) basePower += 150;
if (equip.heater) basePower += 150;
if (lightOn) basePower += 100;

// 기존 장치 상태 노드 호환을 위해 system_state 유지
const system_state = shown.equipOn ? "RECOVERING" : (shown.anomaly ? "ANOMALY" : "NORMAL");

// ===== 5. 출력 =====
const payload = {
    timestamp: Date.now(),
    temperature: parseFloat(temp.toFixed(1)),
    humidity: Math.round(humi),
    co2: Math.floor(co2),
    lux: Math.floor(lux),
    outdoor_lux: Math.floor(outdoor),
    occupied: occupied,
    power_consumption: basePower,
    hvac_status: hvac_status,
    humidity_status: humi_status,
    vent_status: vent_status,
    light_status: light_status,
    system_state: system_state,
    stage: shown.stage,              // 직전 틱 판정
    anomaly_type: shown.anomaly,     // 직전 틱 판정 (temp / tempLow / humi / co2)
    disable_rate_check: s.anomaly !== null
};

// Grafana 상태 화면용 (flow에만 저장)
flow.set('simStatus', {
    timestamp: payload.timestamp,
    stage: shown.stage,
    anomaly_type: shown.anomaly,
    equipment: equip,
    temperature: payload.temperature,
    humidity: payload.humidity,
    co2: payload.co2,
    lux: payload.lux,
    occupied: occupied
});

msg.payload = payload;
return msg;

// 기존 데이터(msg.payload)는 온전히 유지하면서 eCharts 축 제어 옵션을 주입합니다.
msg.ui_update = {
    chartOptions: {
        xAxis: [
            {
                axisLabel: {
                    interval: 0,        // 0으로 지정하면 차트가 임의로 라벨을 생략하지 않고 모두 노출합니다.
                    hideOverlap: false  // 좁은 공간에서 글자가 약간 겹치더라도 숨기지 않고 강제 표시합니다.
                }
            }
        ]
    }
};

return msg;

const p = msg.payload;
if (!p || typeof p !== 'object') return null;

msg.payload = {
    // 냉방기: 온도 이상 조치 중일 때 동작
    cooling: p.system_state === 'RECOVERING' && p.anomaly_type === 'temp',
    // 제습기: 습도 이상 조치 중일 때 동작
    dehumid: p.system_state === 'RECOVERING' && p.anomaly_type === 'humi',
    // 조명: 인원 0명 상태에서 조도가 아직 떨어지는 중이면 소등 애니메이션
    lightFading: !p.occupied && p.lux > 30,
    lux: Math.floor(p.lux),
    state: p.system_state
};

return msg;

msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': 'http://localhost:3000'
};
msg.payload = 'OK';
return msg;

const SECRET = 'demo-token-change-me';
if (msg.req.query.token !== SECRET) {
    msg.statusCode = 403;
    msg.payload = 'Forbidden';
    return msg;
}
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = flow.get('simStatus') || { stage: 'NORMAL', equipment: {} };
return msg;

const SECRET = 'demo-token-change-me';

if (msg.req.query.token !== SECRET) {
    return [msg, null];   // 출력1: 실패
}
return [null, msg];       // 출력2: 통과

msg.statusCode = 403;
msg.headers = { 'Access-Control-Allow-Origin': 'http://localhost:3000' };
msg.payload = 'Forbidden';
return msg;

// 1. 최초 실행 시 10개층 × 4개 룸 (총 40개) 상태 구조 정의
if (!context.rooms) {
    context.rooms = {};
    for (let f = 1; f <= 10; f++) {
        for (let r of ['A', 'B', 'C', 'D']) {
            context.rooms[`${f}F_${r}`] = 0; // 초기 상태는 0명으로 시작
        }
    }
}

// 2. 현재 시각(시) 기준 실시간 시나리오 가이드라인 매핑 (2026년 기준 실시간 감지)
const now = new Date();
const hour = now.getHours();

let targetTotal = 4;        // 시간대별 목표 총 인원 수
let activeChangeRooms = 4;   // 5초마다 인원 변동을 줄 방의 개수 (기본값)
let directionWeight = 0.3;   // 목표 수치 수렴을 위한 가중치 확률

if (hour >= 20 || hour < 7) {
    // 20:00 ~ 07:00 -> 야간/새벽 최소 유지 (1% = 약 4명)
    targetTotal = 4;
    activeChangeRooms = 4;   // 야간에는 가끔씩만 움직임
    directionWeight = 0.1;   // 강력하게 감소/최저 유지 유도
} 
else if (hour >= 7 && hour < 9) {
    // 07:00 ~ 09:00 -> 출근 시간 급격한 증가 (목표 80% = 320명)
    targetTotal = 320;
    activeChangeRooms = 28;  // 출근 피크: 40개 룸 중 28개 룸이 동시에 인원 변동 (급상승 연출)
    directionWeight = 0.85;  // 85% 확률로 무조건 인원 추가(+1) 발생
} 
else if (hour >= 9 && hour < 17) {
    // 09:00 ~ 17:00 -> 낮 일과 시간 유지 (70~80% = 평균 300명)
    targetTotal = 300;
    activeChangeRooms = 6;   // 근무 중에는 룸 내에서만 조금씩 늘거나 줄어듦
    directionWeight = 0.5;   // 균형 유지
} 
else if (hour >= 17 && hour < 18) {
    // 17:00 ~ 18:00 -> 퇴근 시간 1차 급격한 감소 (목표 20% = 80명)
    targetTotal = 80;
    activeChangeRooms = 25;  // 퇴근 피크: 25개 룸이 동시에 인원 감소 (급하강 연출)
    directionWeight = 0.15;  // 85% 확률로 무조건 인원 감소(-1) 발생
} 
else if (hour >= 18 && hour < 20) {
    // 18:00 ~ 20:00 -> 잔류 인원 서서히 감소 (20% -> 1% 서서히 수렴)
    targetTotal = 4;
    activeChangeRooms = 10;  // 잔류조 퇴근: 적당한 속도로 인원 감소
    directionWeight = 0.2;   // 하강 안정화
}

// 3. 무작위 타겟 룸 추출 및 인원 증감 적용
const roomKeysList = Object.keys(context.rooms);
const roomsToChange = roomKeysList.sort(() => 0.5 - Math.random()).slice(0, activeChangeRooms);

// 현재 빌딩 전체 인원 실시간 계산
let currentTotal = Object.values(context.rooms).reduce((a, b) => a + b, 0);

roomsToChange.forEach(key => {
    let currentVal = context.rooms[key];
    let change = 0;

    // 실시간 인원이 목표 타겟보다 적은지 많은지에 따라 가중치 판별
    if (currentTotal < targetTotal) {
        change = Math.random() < directionWeight ? 1 : -1;
    } else {
        change = Math.random() > directionWeight ? -1 : 1;
    }

    // 개별 룸당 Max 10명, Min 0명 절대 한계치 적용
    let newVal = currentVal + change;
    if (newVal > 10) newVal = 10;
    if (newVal < 0) newVal = 0;

    context.rooms[key] = newVal;
    currentTotal = currentTotal - currentVal + newVal; // 집계치 즉시 동기화
});

// 4. InfluxDB v2.x 수신 규격(Tag/Field 구조 배열)으로 포맷 변환
const influxPayload = [];
for (let f = 1; f <= 10; f++) {
    for (let r of ['A', 'B', 'C', 'D']) {
        const key = `${f}F_${r}`;
        influxPayload.push([
            { occupancy: context.rooms[key] }, // Field 데이터 (그라파나에서 숫자로 매핑)
            { floor: `${f}F`, room: r }         // Tag 데이터 (그라파나에서 필터 및 그룹화로 사용)
        ]);
    }
}

msg.payload = influxPayload;
return msg;

// 그라파나가 보낸 쿼리 파라미터는 msg.req.query에 들어있습니다.
const action = msg.req.query.action;
const from = msg.req.query.from;
