    receivedData: {
        action: action,
        from: from
    }
};
return msg;

// =====================================================================
// 가상 빌딩 시뮬레이터
//   ① 명령 처리  →  ② 시나리오 엔진  →  ③ 출력 생성  →  ④ 상태 저장
// =====================================================================

// ---------- 설정 (튜닝은 이 블록만 수정) ----------
const CONFIG = {
    // 이상 종류 정의 (새 이상은 여기에 한 줄 추가)
    scenario: {
        temp:    { sensor: 'temp', dir: 'high', detect: 28,   severe: 30,   ok: 24,  rise: 3.0,  fall: 3.0,  noise: 0.4, cap: 45.0 },
        tempLow: { sensor: 'temp', dir: 'low',  detect: 18,   severe: 15,   ok: 20,  rise: 3.0,  fall: 3.0,  noise: 0.4, cap: 5.0  },
        humi:    { sensor: 'humi', dir: 'high', detect: 60,   severe: 75,   ok: 55,  rise: 8.0,  fall: 11.5, noise: 0.8, cap: 100.0 },
        co2:     { sensor: 'co2',  dir: 'high', detect: 1000, severe: 1300, ok: 900, rise: 250,  fall: 220,  noise: 20,  cap: 3000 }
    },
    autoStartTicks: 2,                                   // 감지 후 이 틱 이상 유지되면 자동 가동
    normalTarget: { temp: 22.0, humi: 45.0, co2: 500, co2Occupied: 650 },  // 정상 센서 목표값
    command: {
        ANOMALY_TEMP: 'temp',
        ANOMALY_TEMP_LOW: 'tempLow',
        ANOMALY_HUMI: 'humi',
        ANOMALY_CO2: 'co2'
    }
};

const SC = CONFIG.scenario;
const noise = (amp) => (Math.random() - 0.5) * amp;

// ---------- 상태 로드 ----------
let s = context.get('state') || {
    anomaly: null, equipOn: false, detectTicks: 0, recovered: false,
    temp: 22.0, humi: 45.0, co2: 550, lux: 350, occupied: false,
    view: null   // 직전 틱 판정 (램프/장비 표시용)
};

// =====================================================================
// ① 명령 처리 (버튼 / HTTP 공통)
// =====================================================================
function extractCommand(m) {
    let raw;
    if (m.req && m.req.query && m.req.query.action !== undefined) {
        raw = m.req.query.action;
    } else if (typeof m.payload === 'string') {
        raw = m.payload;
    }
    if (raw === undefined) return 'TICK';
    return String(raw).trim().toUpperCase();
}

function applyCommand(state, cmd) {
    const anomaly = CONFIG.command[cmd];
    if (anomaly !== undefined) {
        if (state.anomaly !== anomaly) {
            state.anomaly = anomaly;
            state.equipOn = false;
            state.detectTicks = 0;
            state.recovered = false;
        }
    } else if (cmd === 'RESET') {
        state.anomaly = null;
        state.equipOn = false;
        state.detectTicks = 0;
        state.recovered = false;
    } else if (cmd === 'OCCUPY_ON') {
        state.occupied = true;
    } else if (cmd === 'OCCUPY_OFF') {
        state.occupied = false;
    } else if (cmd !== 'TICK') {
        node.warn(`알 수 없는 명령: [${cmd}]`);
    }
}

applyCommand(s, extractCommand(msg));

// =====================================================================
// ② 시나리오 엔진 (이상 수치 변화 · 단계 판정 · 장비 판정)
// =====================================================================
const isBeyond = (L, x, lim) => (L.dir === 'high' ? x >= lim : x <= lim);
const isRecovered = (L, x) => (L.dir === 'high' ? x <= L.ok : x >= L.ok);

// 이상 센서: 이상 방향 변화 / 장비 가동 중에는 정상 방향 변화
function stepAnomaly(state) {
    if (!state.anomaly) return;
    const L = SC[state.anomaly];
    const key = L.sensor;
    const k = (L.dir === 'high') ? 1 : -1;
    if (state.equipOn) state[key] -= k * L.fall + noise(L.noise);
    else               state[key] += k * L.rise + noise(L.noise);
    state[key] = (L.dir === 'high') ? Math.min(state[key], L.cap) : Math.max(state[key], L.cap);
}

// 정상 센서: 목표값 주변 변동 (이상 센서 제외)
function stepNormal(state) {
    const T = CONFIG.normalTarget;
    const anomSensor = state.anomaly ? SC[state.anomaly].sensor : null;
    if (anomSensor !== 'temp') state.temp += (T.temp - state.temp) * 0.1 + noise(0.3);
    if (anomSensor !== 'humi') state.humi += (T.humi - state.humi) * 0.1 + noise(1.0);
    if (anomSensor !== 'co2')  state.co2  += ((state.occupied ? T.co2Occupied : T.co2) - state.co2) * 0.1 + noise(20);
}

// 장비 가동 / 정상 복귀 판정
function judgeScenario(state) {
    if (!state.anomaly) return;
    const L = SC[state.anomaly];
    const v = state[L.sensor];

    if (!state.equipOn) {
        state.detectTicks = isBeyond(L, v, L.detect) ? state.detectTicks + 1 : 0;
        if (isBeyond(L, v, L.severe) || state.detectTicks >= CONFIG.autoStartTicks) {
            state.equipOn = true;
        }
    } else if (isRecovered(L, v)) {
        state.anomaly = null;
        state.equipOn = false;
        state.detectTicks = 0;
        state.recovered = true;
    }
}

// 단계(stage) 계산
function calcStage(state) {
    if (!state.anomaly) return state.recovered ? 'RECOVERED' : 'NORMAL';
    const L = SC[state.anomaly];
    const v = state[L.sensor];
    if (state.equipOn) return 'MITIGATING';
    if (isBeyond(L, v, L.severe)) return 'SEVERE';
    if (isBeyond(L, v, L.detect)) return 'DETECTED';
    return 'ANOMALY';
}

stepAnomaly(s);
stepNormal(s);
judgeScenario(s);
const stage = calcStage(s);

// 조도: 외부 일사량 + 실내 조명
function stepLux(state) {
    const hour = new Date().getHours() + new Date().getMinutes() / 60;
    let outdoor = 0;
    if (hour > 6 && hour < 19) outdoor = Math.sin(Math.PI * (hour - 6) / 13) * 1000;
    outdoor = Math.max(0, outdoor + noise(60));
    const lightOn = state.occupied && outdoor < 400;
    const indoorTarget = outdoor * 0.3 + (lightOn ? 350 : 0);
    state.lux += (indoorTarget - state.lux) * 0.3 + noise(5);
    state.lux = Math.min(Math.max(state.lux, 0), 1000);
    return { outdoor, lightOn };
}
const { outdoor, lightOn } = stepLux(s);

// 직전 틱 판정을 화면/장비 표시에 사용 (수치 변화 이후 점등)
const cur = { anomaly: s.anomaly, equipOn: s.equipOn, stage: stage };
const shown = s.view || cur;
s.view = cur;

context.set('state', s);

// =====================================================================
// ③ 출력 생성 (InfluxDB용 payload, 장비 표시)
