    heater:       shown.anomaly === 'tempLow' && shown.equipOn,
    humidifier:   false,
    dehumidifier: shown.anomaly === 'humi'    && shown.equipOn,
    ahu:          shown.anomaly === 'co2'     && shown.equipOn
};

function calcDeviceStatus(state, eq) {
    let hvac = "OFF";
    if (state.temp > 28) hvac = "COOL_ON";
    else if (state.temp < 18) hvac = "HEAT_ON";
    if (eq.chiller) hvac = "COOL_ON";
    if (eq.heater)  hvac = "HEAT_ON";

    let humi = "OFF";
    if (state.humi < 40) humi = "HUMIDIFIER_ON";
    else if (state.humi > 60) humi = "DEHUMIDIFIER_ON";
    if (eq.dehumidifier) humi = "DEHUMIDIFIER_ON";

    let vent = "OFF";
    if (state.co2 > 1000) vent = "VENT_HIGH";
    else if (state.co2 > 800) vent = "VENT_LOW";
    if (eq.ahu) vent = "AHU_FRESH_AIR";

    return { hvac, humi, vent };
}

function calcPower(dev, eq, lightOn) {
    let p = Math.floor(Math.random() * (520 - 470) + 470);
    if (dev.hvac !== "OFF") p += 200;
    if (eq.dehumidifier) p += 120;
    if (eq.ahu) p += 150;
    if (eq.heater) p += 150;
    if (lightOn) p += 100;
    return p;
}

const dev = calcDeviceStatus(s, equip);
const basePower = calcPower(dev, equip, lightOn);
const light_status = lightOn ? "LIGHT_ON" : "OFF";
const system_state = shown.equipOn ? "RECOVERING" : (shown.anomaly ? "ANOMALY" : "NORMAL");

const payload = {
    timestamp: Date.now(),
    temperature: parseFloat(s.temp.toFixed(1)),
    humidity: Math.round(s.humi),
    co2: Math.floor(s.co2),
    lux: Math.floor(s.lux),
    outdoor_lux: Math.floor(outdoor),
    occupied: s.occupied,
    power_consumption: basePower,
    hvac_status: dev.hvac,
    humidity_status: dev.humi,
    vent_status: dev.vent,
    light_status: light_status,
