    anomaly_type: shown.anomaly,
    disable_rate_check: s.anomaly !== null
};

// 다음 노드(상태 저장)로 전달할 정보
msg.payload = payload;
msg.equip = equip;
return msg;

// Grafana 상태 화면용 (flow 컨텍스트)
const p = msg.payload;

flow.set('simStatus', {
    timestamp: p.timestamp,
    stage: p.stage,
    anomaly_type: p.anomaly_type,
    equipment: msg.equip,
    temperature: p.temperature,
    humidity: p.humidity,
    co2: p.co2,
    lux: p.lux,
    occupied: p.occupied
});

// payload는 그대로 InfluxDB / Postgres 노드로 전달
return msg;

let temp = context.get('temp') || 22.0;
let humi = context.get('humi') || 50.0;
let co2 = context.get('co2') || 600;
let lux = context.get('lux') || 350;
let occupied = context.get('occupied') || false;
let power = context.get('power') || 500;

temp += (Math.random() - 0.5) * 0.4;
humi += (Math.random() - 0.5) * 1.0;
co2 += (Math.random() - 0.5) * 30;
lux += (Math.random() - 0.6) * 50;

let occTimer = context.get('occTimer') || 0;
occTimer++;
if (occTimer > 30) {
    occupied = Math.random() > 0.5;
    occTimer = 0;
}

if (occupied) {
    power += Math.random() * 50;
} else {
    power -= Math.random() * 30;
}

temp = Math.max(15, Math.min(30, temp));
humi = Math.max(20, Math.min(90, humi));
co2 = Math.max(400, Math.min(2500, co2));
lux = Math.max(10, Math.min(1000, lux));
power = Math.max(400, Math.min(1000, power));

context.set('temp', temp);
context.set('humi', humi);
context.set('co2', co2);
context.set('lux', lux);
context.set('occupied', occupied);
context.set('power', power);
context.set('occTimer', occTimer);

msg.payload = {
    timestamp: new Date().toISOString(),
    temperature: parseFloat(temp.toFixed(1)),
    humidity: Math.round(humi),
    co2: Math.round(co2),
    lux: Math.round(lux),
    occupied: occupied,
    power_consumption: Math.round(power)
};

return msg;

const payload = msg.payload;
const issues = [];

if (payload.temperature < 15 || payload.temperature > 30) {
    issues.push('Temperature out of range');
}
if (payload.humidity < 20 || payload.humidity > 90) {
    issues.push('Humidity out of range');
}
if (payload.co2 < 400 || payload.co2 > 2500) {
    issues.push('CO2 out of range');
}

const lastTemp = context.get('lastTemp') || payload.temperature;
if (Math.abs(payload.temperature - lastTemp) > 5) {
    issues.push('Abnormal temp change');
}

context.set('lastTemp', payload.temperature);

msg.payload.quality_score = Math.max(0, 100 - (issues.length * 20));
msg.payload.issues = issues;

return msg;

const p = msg.payload;
const ts = new Date(p.timestamp).toISOString();
if (p.quality_score<100){
msg.topic = `INSERT INTO sensor_data 
(timestamp, temperature, humidity, co2, lux, occupied, power_consumption, quality_score) 
VALUES 
('${ts}', ${p.temperature}, ${p.humidity}, ${p.co2}, ${p.lux}, ${p.occupied}, ${p.power_consumption}, ${p.quality_score})`;
return msg;
}
else {return null;}

// InfluxDB 노드로 가기 직전 Function 노드 예시
if (msg.payload && msg.payload.timestamp) {
    // 문자열을 숫자(Float)로 강제 변환
    msg.payload.timestamp = parseFloat(msg.payload.timestamp);
}
return msg;

return msg;
